// 数据
const operationName = ref('')
const symptoms = ref(['胸痛', '头痛', '发热', '呼吸困难', '恶心呕吐', '腹痛', '头晕'])
const selectedSymptoms = ref([])
const urgency = ref('normal')
const otherNeeds = ref('')

// 从缓存读取预约表单数据 (新增)
let appointmentFormData = ref({});

// --- 新增：响应式数据用于控制匹配动画 ---
const isMatching = ref(false);
// --- 结束新增 ---

onMounted(() => {
  try {
    appointmentFormData.value = uni.getStorageSync('appointmentFormData') || {};
    console.log('【AICareMatchPage】从缓存读取预约表单数据:', appointmentFormData.value);
  } catch (e) {
    console.error('【AICareMatchPage】读取预约表单缓存失败:', e);
    // 如果读取失败，使用空对象，或者提示用户
  }
});

// 操作函数
const toggleSymptom = (index) => {
  if (selectedSymptoms.value.includes(index)) {
    selectedSymptoms.value = selectedSymptoms.value.filter(i => i !== index)
  } else {
    selectedSymptoms.value.push(index)
  }
}

const addOtherSymptom = () => {
  uni.showToast({
    title: '添加其他症状功能未实现'
  })
}

const setUrgency = (level) => {
  urgency.value = level
}

// 紧急程度映射 (API 需要数字) - 保留用于本地逻辑参考
const getEmergencyLevel = (level) => {
  switch (level) {
    case 'normal':
      return 0
    case 'urgent':
      return 1
    case 'emergency':
      return 2
    default:
      return 0
  }
}

// --- 更新 getRecommendation 函数：移除API调用 ---
const getRecommendation = async () => {
  // 校验必要信息
  if (!operationName.value && selectedSymptoms.value.length === 0 && !otherNeeds.value) {
    uni.showToast({
      title: '请填写必要信息',
      icon: 'none'
    })
    return
  }

  // 构造本地匹配数据 (Body)，加入从缓存获取的医院和时间信息
  const localMatchData = {
    demandType: '陪诊',
    emergencyLevel: getEmergencyLevel(urgency.value),
    surgeryName: operationName.value,
    symptoms: selectedSymptoms.value.map(i => symptoms.value[i]),
    otherRequirement: otherNeeds.value,
    // --- 新增：从缓存添加医院和时间 ---
    hospital: appointmentFormData.value.hospitalName || '',
    serviceDate: appointmentFormData.value.serviceDate || '',
    serviceStartTime: appointmentFormData.value.startTime || '',
    serviceEndTime: appointmentFormData.value.endTime || '',
    // --- 结束新增 ---
  }
  console.log('【AICareMatchPage】本地匹配数据 (模拟):', localMatchData)

  // --- 修改：不再执行API请求 ---
  // let isLoadingShown = false;
  // const showMyLoading = () => {
  //   if (!isLoadingShown) {
  //     uni.showLoading({ title: '匹配中...', mask: true });
  //     isLoadingShown = true;
  //   }
  // };
  // const hideMyLoading = () => {
  //   if (isLoadingShown) {
  //     uni.hideLoading();
  //     isLoadingShown = false;
  //   }
  // };
  // showMyLoading();
  // try {
  //   await post(fullApiUrl, requestBody);
  //   // API 成功时，可以选择显示一个提示或不显示
  //   // uni.showToast({ title: '匹配请求已提交', icon: 'success' });
  // } catch (error) {
  //   // API 失败时，不打印错误日志，不显示任何提示
  //   // console.error('匹配请求失败 (已忽略):', error);
  // }
  // hideMyLoading(); // 无论成功失败，都隐藏加载提示
  // --- 结束修改 ---

  // --- 修改：显示匹配动画，然后将当前页面数据合并到缓存并跳转 ---
  // 设置匹配状态为 true，显示动画
  isMatching.value = true;

  // 将当前表单数据和 AI 需求数据合并，为下一步准备
  const updatedFormData = {
    ...appointmentFormData.value, // 包含 hospitalName, serviceDate, startTime, endTime 等
    operationName: operationName.value,
    selectedSymptoms: selectedSymptoms.value,
    urgency: urgency.value,
    otherNeeds: otherNeeds.value,
  };
  console.log('【AICareMatchPage】准备跳转，更新缓存数据:', updatedFormData);
  uni.setStorageSync('appointmentFormData', updatedFormData);

  // 设置一个定时器，在动画效果持续一段时间后（例如1.5秒）再跳转
  setTimeout(() => {
    // 匹配结束后，将匹配状态设为 false，隐藏动画
    isMatching.value = false;
    uni.navigateTo({
      url: `/pages/ServiceCompanionSelect/ServiceCompanionSelect` // 移除 appointmentId 参数
    });
  }, 1500); // 1500毫秒后跳转，与之前的延迟保持一致
  // --- 结束修改 ---
}

// --- 结束更新 getRecommendation 函数 ---
